import './App.css';

import Festval_serch_details from "./component/Festval_serch_details.js";
import Festval_list_card from "./component/Festval_list_card.js";
import axios from 'axios';
import { useState } from 'react';

const App= () => {  

  const [data, setData] = useState(null);

  const Loging = async() => {
    try{
      const response = await axios.get("http://apis.data.go.kr/B551011/KorService1/searchFestival1?serviceKey=Av0j4qFKXlogzFTNST8uPV8AmR6bdc5h9gNecQv1RR7v92yhfpCYFHj19OoN6mlq00fxLxYyEif4u5cu2GP%2BQA%3D%3D"+
        "numOfRows=10&pageNo=1&MobileOS=ETC&MobileApp=AppTest&arrange=A&listYN=Y&eventStartDate=202401101");
        setData(response.data); 
        console.log(JSON.stringify(data))       ;
    }catch(e){
      console.log(e);
    }
  };

  console.log(Loging);

  return (
    <section id='main_conteiner'>
      <section className='left_box'></section> {/** 프로젝트 로고삽입 */}
      <section className='right_box'>
        <Festval_serch_details />
        <div className='card_list'>
          <Festval_list_card />
        </div>
      </section>
    </section>    
  );
}

export default App;
